const vidInput = String(tobub.params.vid || '').trim();
const count = Number(tobub.params.count ?? 15);
const maxScrollTimes = Number(tobub.params.maxScrollTimes ?? 6);
const sortBy = String(tobub.params.sortBy ?? 'platform');
const pageLoadWaitSeconds = Number(tobub.params.pageLoadWaitSeconds ?? 4);
const tabWaitSeconds = Number(tobub.params.tabWaitSeconds ?? 2);
const scrollWaitSeconds = Number(tobub.params.scrollWaitSeconds ?? 1.2);
const saveResults = tobub.params.saveResults !== false;
if (!vidInput || vidInput.length > 2048) throw new Error('Enter a TikTok video ID or URL.');
if (!Number.isInteger(count) || count < 1 || count > 100) throw new Error('count must be an integer from 1 to 100.');
if (!Number.isInteger(maxScrollTimes) || maxScrollTimes < 1 || maxScrollTimes > 10) throw new Error('maxScrollTimes must be an integer from 1 to 10.');
if (!['platform', 'newest', 'mostLiked'].includes(sortBy)) throw new Error('Invalid sortBy value.');
if (!Number.isInteger(pageLoadWaitSeconds) || pageLoadWaitSeconds < 2 || pageLoadWaitSeconds > 15) throw new Error('pageLoadWaitSeconds must be from 2 to 15 seconds.');
if (!Number.isInteger(tabWaitSeconds) || tabWaitSeconds < 1 || tabWaitSeconds > 10) throw new Error('tabWaitSeconds must be from 1 to 10 seconds.');
if (!Number.isFinite(scrollWaitSeconds) || scrollWaitSeconds < 0.5 || scrollWaitSeconds > 5) throw new Error('scrollWaitSeconds must be from 0.5 to 5 seconds.');
const allowedHosts = new Set(['tiktok.com', 'www.tiktok.com', 'm.tiktok.com']);
let videoId = vidInput;
let videoUrl;
if (/^\d{8,24}$/.test(vidInput)) {
  videoUrl = 'https://www.tiktok.com/video/' + vidInput;
} else {
  let parsed;
  try { parsed = new URL(/^[a-z][a-z0-9+.-]*:\/\//i.test(vidInput) ? vidInput : 'https://' + vidInput); }
  catch { throw new Error('Invalid TikTok video URL.'); }
  if (!allowedHosts.has(parsed.hostname.toLowerCase()) || !['http:', 'https:'].includes(parsed.protocol)) throw new Error('Use an official TikTok video URL or video ID.');
  const match = parsed.pathname.match(/\/video\/(\d{8,24})(?:\/|$)/);
  if (!match) throw new Error('The video URL must contain a numeric video ID after /video/.');
  videoId = match[1];
  videoUrl = 'https://www.tiktok.com' + parsed.pathname;
}
const watch = await tobub.browser.network.watch({
  id: 'tiktok-video-comments',
  urlPattern: { pattern: 'api/comment/list' },
  resourceTypes: ['xhr', 'fetch'],
  captureResponseBody: true,
  maxBodyBytes: 2000000,
  maxRecords: 80
});
let videoContentItemId = null;
if (saveResults) {
  const videoContent = await tobub.db.saveContent({
    platform: 'tiktok',
    contentType: 'video',
    externalId: videoId,
    title: 'TikTok video ' + videoId,
    url: videoUrl,
    rawData: { videoId, videoUrl }
  });
  if (!videoContent || !Number.isFinite(Number(videoContent.contentItemId))) throw new Error('Failed to save the video association.');
  videoContentItemId = Number(videoContent.contentItemId);
}
await tobub.atoms.navigate({ url: videoUrl, waitUntil: 'domcontentloaded' });
await tobub.atoms.waitFor({ delay: pageLoadWaitSeconds * 1000 });
let commentsTabClicked = false;
const tabReady = await tobub.atoms.condition({
  type: 'count',
  selector: 'button[data-testid="tux-web-tab-bar"]',
  comparison: 'gte',
  value: 1,
  pollInterval: 100,
  throwOnTimeout: false
}, { timeout: 1500 });
if (tabReady && tabReady.satisfied) {
  try {
    await tobub.atoms.click({ selector: 'button[data-testid="tux-web-tab-bar"]', nth: 0, visibleOnly: true });
    commentsTabClicked = true;
  } catch {}
}
await tobub.atoms.waitFor({ delay: tabWaitSeconds * 1000 });
for (let i = 0; i < maxScrollTimes; i++) {
  const stateResult = await tobub.atoms.evaluate({
    mode: 'expression',
    expression: '(()=>{const marker=document.querySelector("[data-e2e=\\"comment-level-1\\"]");let el=marker;for(let i=0;i<8&&el;i++,el=el.parentElement){const s=getComputedStyle(el);if(el.scrollHeight>el.clientHeight+40&&/(auto|scroll)/.test(s.overflowY)){const before=el.scrollTop;el.scrollTop=Math.min(el.scrollHeight,el.scrollTop+Math.max(300,el.clientHeight*0.8));return{found:true,before,after:el.scrollTop,height:el.scrollHeight}}}return{found:false,count:document.querySelectorAll("[data-e2e^=\\"comment-level-\\"]").length}})()'
  });
  const state = stateResult && stateResult.value !== undefined ? stateResult.value : stateResult;
  if (!state || !state.found || (state.after <= state.before && state.before > 0)) break;
  await tobub.atoms.waitFor({ delay: scrollWaitSeconds * 1000 });
}
const networkRecords = await tobub.browser.network.collect(watch, { stop: true });
const pages = [];
for (const record of networkRecords) {
  const body = record?.response?.body;
  if (typeof body !== 'string' || record.response.bodyEncoding === 'base64') continue;
  if (record.response.status && (record.response.status < 200 || record.response.status >= 300)) continue;
  let requestUrl, payload;
  try { requestUrl = new URL(record.request.url); payload = JSON.parse(body); } catch { continue; }
  if (!requestUrl.pathname.includes('/api/comment/list/')) continue;
  if (requestUrl.searchParams.get('aweme_id') && requestUrl.searchParams.get('aweme_id') !== videoId) continue;
  const rows = Array.isArray(payload?.comments) ? payload.comments : [];
  if (rows.length) pages.push({ rows, cursor: String(payload.cursor ?? ''), hasMore: payload.has_more === true || payload.has_more === 1 });
}
const byId = new Map();
for (const page of pages) {
  for (const comment of page.rows) {
    if (!comment || typeof comment !== 'object') continue;
    const commentId = String(comment.cid ?? comment.comment_id ?? '');
    const text = String(comment.text ?? comment.comment ?? '').trim();
    if (!commentId || byId.has(commentId) || !text) continue;
    const user = comment.user && typeof comment.user === 'object' ? comment.user : {};
    byId.set(commentId, {
      commentId,
      videoId,
      text,
      username: String(user.unique_id ?? user.uniqueId ?? ''),
      nickname: String(user.nickname ?? user.nick_name ?? ''),
      avatarUrl: String(user.avatar_thumb?.url_list?.[0] ?? user.avatar_thumb ?? ''),
      createTime: Number.isFinite(Number(comment.create_time)) ? Math.trunc(Number(comment.create_time)) : null,
      likeCount: Number.isFinite(Number(comment.digg_count)) ? Math.trunc(Number(comment.digg_count)) : null,
      replyCount: Number.isFinite(Number(comment.reply_comment_total)) ? Math.trunc(Number(comment.reply_comment_total)) : null,
      isAuthor: comment.is_author_digged === true,
      dataSource: 'api_comment_list'
    });
  }
}
let fallbackUsed = false;
if (byId.size === 0) {
  const domResult = await tobub.atoms.evaluate({
    mode: 'expression',
    expression: '(()=>Array.from(document.querySelectorAll("[data-e2e^=\\"comment-level-\\"]")).map((el,i)=>{const u=el.querySelector("[data-e2e^=\\"comment-username-\\"]");const text=(el.innerText||"").trim();return{commentId:"dom-"+i,text,username:u?(u.innerText||"").trim():"",nickname:u?(u.innerText||"").trim():""}}).filter(x=>x.text))()'
  });
  const rows = domResult && domResult.value !== undefined ? domResult.value : (domResult && domResult.result !== undefined ? domResult.result : domResult);
  if (Array.isArray(rows)) {
    for (const row of rows) {
      if (!byId.has(row.commentId)) byId.set(row.commentId, { ...row, videoId, avatarUrl: '', createTime: null, likeCount: null, replyCount: null, isAuthor: false, dataSource: 'comment_dom_fallback' });
    }
    fallbackUsed = byId.size > 0;
  }
}
const orderedComments = Array.from(byId.values());
if (sortBy === 'newest') orderedComments.sort((a, b) => (b.createTime ?? -1) - (a.createTime ?? -1));
if (sortBy === 'mostLiked') orderedComments.sort((a, b) => (b.likeCount ?? -1) - (a.likeCount ?? -1));
const comments = [];
for (const comment of orderedComments.slice(0, count)) {
  let contentItemId = null;
  if (saveResults) {
    const saved = await tobub.db.saveContent({
      platform: 'tiktok',
      contentType: 'comment',
      externalId: videoId + ':' + comment.commentId,
      ...(videoContentItemId ? { parentId: videoContentItemId } : {}),
      title: comment.text || 'TikTok comments',
      summary: comment.nickname || comment.username,
      url: videoUrl,
      metadata: { ...comment, sortBy },
      rawData: { ...comment, sortBy }
    });
    if (!saved || !Number.isFinite(Number(saved.contentItemId))) throw new Error('Failed to save comments: ' + comment.commentId);
    contentItemId = Number(saved.contentItemId);
  }
  comments.push({ ...comment, contentItemId });
}
const lastPage = pages.length ? pages[pages.length - 1] : null;
const complete = comments.length >= count || Boolean(lastPage && !lastPage.hasMore);
return {
  videoId,
  videoUrl,
  requestedCount: count,
  returnedCount: comments.length,
  pagesRead: pages.length,
  commentsTabClicked,
  sortBy,
  saved: saveResults,
  savedCount: saveResults ? comments.length : 0,
  complete,
  warning: comments.length === 0 ? 'No comments were read from the page. TikTok may require login, comments may be disabled, or the page may still be loading. If prompted to log in, retry with a verified TikTok Profile.' : (complete ? '' : (fallbackUsed ? 'Some comments were read from the currently rendered DOM, so the result may not include every comment.' : 'Available comments were returned. Increase maxScrollTimes and retry to load more.')),
  comments
};
